import React, {useEffect, useState} from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import NewsItem from './NewsItem';
import { Container, Row, Col } from 'react-bootstrap';

const NewsList: React.FC = () => {
  const { articles, status, author } = useSelector((state: RootState) => state);
  const [filteredArticles, setFilteredArticles] = useState(articles);

  useEffect(() => {
    // ✅ Apply frontend filtering
    const filtered = articles.filter(article => {
      const articleAuthor = author ? author.toString().trim().toLowerCase() : '';
      return author === '' || articleAuthor.includes(author.trim().toLowerCase());
    });

    setFilteredArticles(filtered);
  }, [author, articles]);

  if (status === 'loading') return <p>Loading...</p>;
  if (status === 'failed') return <p>Failed to load news.</p>;


  return (
    <Container>
      <Row>
        {filteredArticles && filteredArticles.length > 0 ? (
          filteredArticles.map((article: any, index: number) => (
            <Col key={index} md={4} sm={6} xs={12} className="mb-4">
              <NewsItem article={article} />
            </Col>
          ))
        ) : (
          <p className="text-center">No articles found</p>
        )}
      </Row>
    </Container>
  );
};

export default NewsList;
